INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000000, '2022', 1, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":1,"q":"The structure marked A in the image below gives rise to which of the following structures?","o":["Gastrosplenic ligament","Lienorenal ligament","Falciform ligament","Gastrophrenic ligament"],"a":2,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":true}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000001, '2022', 2, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":2,"q":"A patient underwent surgery for the varicose vein. He now complains of sensory loss over the medial aspect of the leg and foot. Which of the following nerves is most likely to be injured?","o":["Sural nerve","Superficial peroneal nerve","Deep peroneal nerve","Saphenous nerve"],"a":3,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000002, '2022', 3, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":3,"q":"Identify the given structure?","o":["Lymph node","Glomerulus","Spleen","Pancreatic islet cells"],"a":3,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000003, '2022', 4, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":4,"q":"Identify the mask in the image used for patients with COVID-19 injection.","o":["Venturi mask","Hudson mask","Nebuliser","Non-rebreathing mask"],"a":3,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":true}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000004, '2022', 5, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":5,"q":"A patient from a Mediterranean country visits Africa, where he develops malaria. He is treated with primaquine and later develops hemolytic anemia. Deficiency of an enzyme involved in which of the following pathways could be the cause?","o":["Glycolysis","Gluconeogenesis","Hexose monophosphate (HMP) pathway","Luebering-Rapoport pathway"],"a":2,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000005, '2022', 6, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":6,"q":"A patient presents to you with multiple anogenital warts. The biopsy of these lesions showed squamous atypia. Which of the following human papillomavirus types are considered high-risk?","o":["HPV 2","HPV 18","HPV 6","HPV 11"],"a":1,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000006, '2022', 7, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":7,"q":"A 5-year-old child presents with reduced hearing for the past 2-3 months. The otoscopy finding is given below. What is the most likely diagnosis?","o":["Myringitis bullosa","Serous otitis media","Acute otitis media","Pneumo Tympanum"],"a":1,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000007, '2022', 8, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":8,"q":"Identify the structure given in the image.","o":["Malleus","Incus","Stapes","Vomer"],"a":1,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":true}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000008, '2022', 9, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":9,"q":"A 56-year-old man presents with fatigue, pallor, and abdominal pain. He reports memory loss and reveals that he works at a battery recycling plant. On examination, a noticeable foot drop in both lower extremities is seen. Laboratory testing shows elevated blood lead levels. Which enzyme is affected in the given scenario?","o":["Aminolevulinic acid (ALA) dehydratase","Uroporphyrinogen III","Uroporphyrinogen I","Pyruvate dehydrogenase"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000009, '2022', 10, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":10,"q":"A patient came with complaints of hair loss. His wife mentions that she has noticed some behavioral changes. The doctor notices a loss of eyebrows on the lateral side. He then concludes by examining the nails. What is the type of poisoning in this case?","o":["Thallium","Arsenic","Mercury","Lead"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000010, '2022', 11, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":11,"q":"The cerebrospinal fluid (CSF) specimen of a patient is shown below along with the microscopy. The report shows mononuclear cytosis, elevated proteins, and low sugars. Which of the following is the likely etiology?","o":["Tuberculous meningitis","Aseptic meningitis","Bacterial meningitis","Chemical meningitis"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000011, '2022', 12, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":12,"q":"A female patient presents to you with a unilateral headache. It is associated with nausea, photophobia, and phonophobia. What is the drug of choice for acute management?","o":["Flunarizine","Sumatriptan","Propranolol","Topiramate"],"a":1,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000012, '2022', 13, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":13,"q":"A patient presents to you with fever, night sweats, ptosis, and bilateral facial nerve palsy. Investigations showed leukocytosis and bilateral hilar lymphadenopathy. Which of the following is the most likely diagnosis?","o":["Sarcoidosis","Tuberculosis","Lymphoma","Hypersensitive pneumonitis"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000013, '2022', 14, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":14,"q":"A 25-year-old patient is undergoing tooth extraction for dental caries. Which of the following does not require prophylaxis against infective endocarditis?","o":["Prior history of endocarditis","Atrial septal defect","Unrepaired cyanotic heart disease","Prosthetic heart valves"],"a":1,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000014, '2022', 15, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":15,"q":"A patient presents to the emergency department with a history of ingestion of ten tablets of paracetamol. He has developed oliguria and liver function tests show deranged values. Which of the following can be used in the management of this condition?","o":["N-acetylcysteine","Dopamine","Ursodeoxycholic acid","Furosemide"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000015, '2022', 16, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":16,"q":"A patient presents to you with an irregularly irregular pulse of 120/minutes and a pulse deficit of 20. Which of the following would be the jugular venous pressure (JVP) finding?","o":["Absent p wave","Absent a wave","Cannon a wave","Raised JVP with normal waveform"],"a":1,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000016, '2022', 17, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":17,"q":"A patient with a history of chronic liver disease presents with abdominal distension, jaundice, and pruritis. Ascitic fluid analysis revealed a neutrophil count >650 per cubic mm. What is the most likely diagnosis?","o":["Spontaneous bacterial peritonitis","Malignant ascites","Tubercular ascites","Intestinal obstruction"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000017, '2022', 18, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":18,"q":"Laboratory investigations of a patient being evaluated for jaundice show elevated bilirubin and alkaline phosphatase levels. Levels of the remaining liver enzymes are normal. What is the likely diagnosis?","o":["Obstructive jaundice","Hemolytic jaundice","Hepatic jaundice","Prehepatic jaundice"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000018, '2022', 19, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":19,"q":"An 11-year-old child with a history of streptococcal pharyngitis presents you with fever and arthralgia. There is no past history of rheumatic heart disease or features of carditis or valvular disease. How often is 6,00,000 IU of benzathine penicillin recommended for prophylaxis of rheumatic heart disease?","o":["Immediately","Thrice weekly lifelong","Once in three weeks for 5 years or till the age of 18, whichever is longer","Once in three weeks for 10 years or till the age of 25, whichever is longer"],"a":2,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000019, '2022', 20, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":20,"q":"Which of the following is not seen in MEN 2B syndrome?","o":["Megacolon","Parathyroid adenoma","Mucosal neuroma","Marfanoid habitus"],"a":1,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000020, '2022', 21, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":21,"q":"A patient with coronary artery disease presents to you with chest pain and palpitations. The ECG is shown below. Which of the following can be used in the management?","o":["Oral metoprolol","Oral amiodarone","Intravenous amiodarone","Intravenous metoprolol"],"a":2,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000021, '2022', 22, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":22,"q":"Microfilariae with sheathed tail and two nuclei at the tail is suggestive of?","o":["Wuchereria bancrofti","Brugia malayi","Loa loa","Onchocerca volvulus"],"a":1,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000022, '2022', 23, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":23,"q":"A pregnant lady with 34 weeks of amenorrhea has the following findings: LDH- 700 IU/L, platelets – 75,000/mm3, serum bilirubin- 1.5mg/dL, SGOT-200 U/L, SGPT-150U/L, and BP -140/96 mm Hg. Her coagulation profile and renal function tests are normal. What is the diagnosis? LDH- Lactate dehydrogenase SGOT- Serum glutamic-oxaloacetic transaminase / AST- Asparate transaminase SGPT- Serum glutamic pyruvic transaminase / ALT- Alanine transaminase","o":["HELLP syndrome","Acute fatty liver of pregnancy","Viral hepatitis","Intrahepatic cholestasis"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000023, '2022', 24, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":24,"q":"A woman at 26 weeks of gestation presents for routine evaluation. On examination, fundal height corresponds to 24 weeks. Ultrasonography revealed decreased amniotic fluid. Which of the following conditions would have led to this presentation?","o":["Renal agenesis","Tracheoesophageal fistula","Cardiac abnormalities","Ureteral stricture"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000024, '2022', 25, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":25,"q":"A type 1 diabetic mother is on magnesium sulfate infusion post – cesarean section for preeclampsia. She develops delirium and is drowsy. She has a respiratory rate of 10/min, random blood glucose level of 240 mg / dL, oliguria, and bilaterally absent knee reflex. What is the cause of her condition?","o":["Magnesium sulfate toxicity","Diabetic ketoacidosis","Eclampsia","Diabetes insipidus"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000025, '2022', 26, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":26,"q":"Identify the type of hymen shown in the image.","o":["Imperforate hymen","Semilunar hymen","Septate hymen","Annular hymen"],"a":2,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":true}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000026, '2022', 27, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":27,"q":"While discharging a patient who underwent a vesicovaginal fistula repair, which of the following would you recommend?","o":["Sexual abstinence for 3 months and avoid pregnancy for a year","Sexual abstinence for 3 weeks and avoid pregnancy for 6 months","Sexual abstinence for 6 weeks and avoid pregnancy for a year","Sexual abstinence for 6 months and avoid pregnancy for 6 years"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000027, '2022', 28, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":28,"q":"Which of the following is an absolute contraindication for the insertion of the device shown in the image below?","o":["Menstruation","Trophoblastic disease","Immediately after delivery","Ruptured condom during intercourse"],"a":1,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":true}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000028, '2022', 29, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":29,"q":"A 20 year old woman is evaluated for primary infertility. Hysterosalpingography was done and reveals the finding shown below. What is the anomaly seen in the image?","o":["Septate uterus","Uterine didelphys","Bicornuate uterus","Unicornuate uterus"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":true}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000029, '2022', 30, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":30,"q":"A pregnant woman with no other comorbid conditions develops preeclampsia. She enquires about the cause of her condition. The doctor explains that it is due to the failure of the invasion of:","o":["Spiral artery by villous trophoblasts","Radial artery by cytotrophoblasts","Spiral artery by extravillous trophoblasts","Arcuate artery by extravillous trophoblasts"],"a":2,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000030, '2022', 31, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":31,"q":"A woman with an obstetric score of G2P1 comes to the clinic at 14 weeks of gestation for her antenatal checkup. A uterine artery doppler was suggested by the doctor. What would it detect?","o":["Early onset preeclampsia","Late – onset preeclampsia","Fetal growth restriction","Placenta accreta"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000031, '2022', 32, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":32,"q":"While conducting a delivery, you perform the maneuver shown below. Following this, there is incomplete separation of the placenta and massive hemorrhage. What is your next step in management?","o":["Start oxytocin infusion and wait for spontaneous delivery of placenta","Uterine massage","Arrange for blood and use Crede’s method for placental delivery","Manual removal of placenta"],"a":3,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000032, '2022', 33, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":33,"q":"A female patient collapses soon after delivery. There is profuse bleeding and features of disseminated intravascular coagulation. Which of the following is the most likely etiology?","o":["Amniotic fluid embolism","Uterine prolapse","Peripartum cardiomyopathy","Rupture of the uterus"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000033, '2022', 34, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":34,"q":"You are examining a multigravida in the second stage of labor for the past two hours. On examination, contractions are adequate, the cervix is dilated with the head at station 0 with molding 2+ and caput 2+. The sagittal suture is in the right occipitotransverse position. The fetal heart rate is 140 beats / minute. Which of the following is carried out for the management of this patient?","o":["Midpelvic forceps","Vacuum -assisted delivery","Wait for an hour for spontaneous labor","Lower segment cesarean section"],"a":3,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000034, '2022', 35, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":35,"q":"A primigravida presents to the labor room at 40 weeks of gestation with lower abdominal pain. She has been in labor for 3 hours. Which of the following will determine if she is in active labor?","o":["Fetal head 5/5 palpable on abdominal examination","Two contractions lasting for 10 seconds in 10 minutes","More than 5 cm cervical dilatation with complete effacement","Rupture of membranes"],"a":2,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000035, '2022', 36, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":36,"q":"Identify the blue – colored area shown in the image below","o":["Obstetric outlet","Anatomical outlet","Pelvic inlet","Midpelvis"],"a":3,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":true}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000036, '2022', 37, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":37,"q":"What will be the level of the uterus on the second – day post delivery?","o":["One finger breadth below umbilicus","Two finger breadths below umbilicus","Three finger breadths below umbilicus","Four finger breadths below umbilicus"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000037, '2022', 38, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":38,"q":"A primigravida woman at 12 weeks of gestation comes to the antenatal clinic for nutritional advice. Which of the following will you recommend?","o":["Additional 300 kcal in 2nd trimester","Additional 300 kcal in 1st trimester","Additional 400 kcal in 3rd trimester","Additional 300 kcal throughout the pregnancy"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000038, '2022', 39, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":39,"q":"A 40 year old G2P1 woman with 18 weeks of amenorrhea comes with a dilated cervix. The cervical length is 15 mm. In spite of explaining the risks, she insisted on cerclage. Which of the following is a contraindication for cervical cerclage?","o":["Ruptured membranes","Prolapse of membranes into the vagina","Fetal fibronectin positive","Advanced maternal age"],"a":1,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000039, '2022', 40, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":40,"q":"A primigravida presents to the emergency room in the early stage of labor with adequate uterine contractions. On per vaginal examination, a gynecoid pelvis is felt, the membranes are ruptured, and the vertex is felt in the right occipito- posterior position. How will you manage this patient?","o":["Vacuum – assisted delivery","Cesarean section","Normal vaginal delivery","Forceps delivery"],"a":2,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000040, '2022', 41, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":41,"q":"A pregnant patient, with a history of classical cesarean section in view of fetal growth retardation in the previous pregnancy, presents to you. She is currently at 35 weeks of gestation with breech presentation. What is the next step in management?","o":["Cesarean section at 37 weeks","Advice USG and visit after 2 weeks","Internal podalic version followed by vaginal delivery","External cephalic version at 36 weeks"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000041, '2022', 42, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":42,"q":"A primigravida at 22 weeks of gestation presents to you with profuse vaginal bleeding. Her blood pressure and glucose levels are within normal limits. Placental implantation at which of the following sites can cause this?","o":["Internal OS","Fallopian tube","Ovarian","Abdominal"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000042, '2022', 43, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":43,"q":"A female patient presents to you with six weeks of amenorrhea, associated with abdominal pain and vaginal bleeding with normal blood pressure. Investigations revealed beta – hCG to be 1400 mIU/mL. An ultrasound scan was done which showed a trilaminar endometrium with normal adnexa. What is the next best step in the management of this patient ?","o":["Repeat beta – hCG after 48 hours","Repeat ultrasound after 3 days","Measurement of progesterone","Laparoscopy"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000043, '2022', 44, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":44,"q":"A 24 year old lactating female with an 18 month old child comes with a history of irregular, heavy bleeding seeking contraceptive advice. Which is the contraceptive of choice?","o":["Progestasert","Copper – T 380A","Mala","Norethisterone enanthate – depot injection"],"a":2,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
