INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000087, '2022', 88, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":88,"q":"An elderly patient presents with anemia and hemoglobinuria. Investigations reveal increased lactate dehydrogenase (LDH). The peripheral smear image is given below. Which of the following physical examination findings can support the likely diagnosis?","o":["Splenomegaly","Frontal bossing","Mechanical second heart sound","Goitre"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":true}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000088, '2022', 89, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":89,"q":"All of the following statements are true regarding neutrophil extracellular trapping (NET) except that","o":["It is detected in blood during sepsis","It is produced in response to bacterial infection","Mitochondrial DNA is seen","It is chromatin with antibacterial enzymes"],"a":2,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000089, '2022', 90, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":90,"q":"Identify the gun that caused the wound and the range of the shot.","o":["Shotgun, intermediate range","Shotgun, close range","Pistol, near shot","Pistol, close shot"],"a":2,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000090, '2022', 91, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":91,"q":"A patient underwent cystoscopy, which showed multiple yellow-white plaques in the trigone of the bladder. The histopathology image is given below. What is the diagnosis?","o":["Interstitial cystitis","Malakoplakia","Polypoid cystitis","Acute cystitis"],"a":1,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":true}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000091, '2022', 92, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":92,"q":"Identify the type of wound from the image.","o":["Defense wounds","Antemortem wound","Postmortem wound","Hesitation cuts"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":true}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000092, '2022', 93, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":93,"q":"Which of the following measures are associated with an increased life span?","o":["Moderate of regular exercise for 30 min","Decrease stress","Decreasing calorie intake by 30 percent","Pharmacological intervention with proton pump inhibitors"],"a":2,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000093, '2022', 94, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":94,"q":"A 45-year-old female patient is told about the benefits and complications of a hysterectomy, and she agrees to the procedure. What kind of consent is this?","o":["Informed consent","Implied consent","Opt-out","Passive consent"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000094, '2022', 95, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":95,"q":"A 56-year-old man was diagnosed with COVID-19 and was put on mechanical ventilation. He passed away after a week. What is the likely post-mortem change seen in the lungs?","o":["Thick layer of fibrin lining the alveoli","Acute and chronic alveolar hemorrhage","Perivascular cuffing","Pulmonary artery hypertrophy with increased resistance"],"a":1,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000095, '2022', 96, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":96,"q":"A dead body is brought for evaluation. On post-mortem examination, a ligature completely encircled the neck, horizontal, and below the thyroid level was seen. There was no dribbling of saliva. What is the cause of death?","o":["Throttling","Ligature strangulation","Gagging","Hanging"],"a":1,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000096, '2022', 97, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":97,"q":"A surgeon returns home from a party after many pegs of alcohol and is called to perform an emergency operation. During the operation, the assisting staff noticed the surgeon’s handshaking and the instruments falling. He eventually nicks an artery, and the patient collapses. Under which of the following terms will this incident be tried?","o":["Criminal negligence","Civil negligence not amounting to criminal negligence","Therapeutic misadventure","Dichotomy"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000097, '2022', 98, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":98,"q":"During the court proceedings, the defense lawyer asks a leading question, which the prosecutor appeals against. The judge grants the appeal. Leading questions are not allowed in all of the following except?","o":["Re-examination","Cross-examination","Examination in chief","Dying declaration"],"a":1,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000098, '2022', 99, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":99,"q":"A female patient presented with fatigue and a history of piles. Routine complete blood count analysis showed hemoglobin of 9 g/dL, MCV 60fL, and RBC count of 5.2 million. A peripheral smear is given below. Which of the following is the next best investigation for this patient?","o":["HbA2 levels","Serum ferritin levels","Serum folate levels","Serum homocysteine levels"],"a":1,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000099, '2022', 100, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":100,"q":"A 56-year-old man presents with dragging pain in the abdomen. On examination, there is massive splenomegaly. Peripheral smear shows leukocytesis with increased myelocytes, metamyelocytes and basophils. Which of the following translocations is seen in this condition?","o":["t(9;22)","t(8;22)","t(15;17)","t(8;14)"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000100, '2022', 101, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":101,"q":"A patient with diabetes mellitus for the past 5 years presents with vomiting and abdominal pain. She is non-compliant with medication and appears dehydrated. Investigations revealed a blood sugar value of 500 mg/dl and the presence of ketone bodies. What is the next best step in management?","o":["Intravenous fluids with long-acting insulin","Intravenous fluids","Intravenous insulin","Intravenous fluids with regular insulin"],"a":3,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000101, '2022', 102, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":102,"q":"A patient diagnosed to be retro-positive was started on highly active antiretroviral therapy (HAART). Which of the following can be used to monitor treatment efficacy?","o":["CD4+ T cell count","Viral load","p24 antigen","Viral serotype"],"a":1,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000102, '2022', 103, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":103,"q":"A hypertensive patient who is non-compliant with medication presents to you with sudden onset breathlessness. A chest x-ray was done, which is shown below. How will you manage this patient?","o":["Intravenous salbutamol","Intravenous nitro-glycerine","Nebulization with salbutamol","Oxygen and antibiotics"],"a":1,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000103, '2022', 104, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":104,"q":"A 1 day- old neonate has not passed urine since birth. What is the next step in management?","o":["a.Continue breast feeding not observed","Admit to NICU’","Start artificial feeding","Start intravenous fluids"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000104, '2022', 105, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":105,"q":"A patient on anti-depressants presented to you with hypotension. An ECG was done, which showed wide QRS complexes and right axis deviation. How will you manage this patient?","o":["Antiarrhythmics","Intravenous sodium bicarbonate","Propranolol","Phenytoin"],"a":1,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000105, '2022', 106, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":106,"q":"A 35-year-old female patient presents to you with fever, breathlessness, and cough with expectoration. A CT scan was done which is shown below. What is the most likely diagnosis?","o":["Consolidation with air bronchogram","Mediastinal mass","Pleural effusion","Diaphragmatic hernia"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000106, '2022', 107, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":107,"q":"A 7 – year old boy presented with abdominal pain, vomiting, oliguria, and periorbital puffiness following chemotherapy. Investigations reveal hyperuricemia, raised creatinine levels, and hyperkalemia. What is the next best step in the management of this condition ?","o":["Hydration","Probenecid","Allopurinol","Rasburicase"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000107, '2022', 108, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":108,"q":"A baby presented with abdominal pain. On examination, a mass is palpated in the right lumbar region. A barium enema is done, and the image is given below. What is the likely diagnosis?","o":["Intussusception","Volvulus","Duodenal atresia","Intestinal obstruction"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":true}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000108, '2022', 109, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":109,"q":"A female patient with a negative urine pregnancy test presents to you with galactorrhea. An MRI was done which revealed a large pituitary tumor. If the patient is not willing for surgery, which of the following is the best drug for treatment?","o":["Bromocriptine","Promethazine","Octreotide","Clozapine"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000109, '2022', 110, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":110,"q":"A woman presents to you with fever, arthralgia, ulcers, fatigue for the past six months, and new-onset hematuria. Urine examination reveals RBC casts and proteinuria. What is the likely diagnosis?","o":["Acute interstitial nephritis","Poststreptococcal glomerulonephritis","Lupus nephritis","IgA nephropathy"],"a":2,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000110, '2022', 111, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":111,"q":"A man on diuretics presents with weakness. An ECG was done which showed flat T waves and prominent U waves. What is the most likely diagnosis?","o":["Hypokalaemia","Hyperkalaemia","Hypomagnesemia","Hypernatremia"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000111, '2022', 112, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":112,"q":"A male patient presents to the emergency department. The arterial blood gas report is as follows: pH, 7.2; pCO2, 81 mmHg; and HCO3, 40meq/L. which of the following is the most likely diagnosis?","o":["Respiratory alkalosis","Metabolic acidosis","Respiratory acidosis","Metabolic alkalosis"],"a":2,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000112, '2022', 113, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":113,"q":"Multidrug-resistant (MDR) tuberculosis shows resistance to which of the following drugs?","o":["Isoniazid, rifampicin, and fluoroquinolone","Fluoroquinolones","Isoniazid and rifampicin","Isoniazid, rifampicin, and kanamycin"],"a":2,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000113, '2022', 114, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":114,"q":"A patient presents to you with a fever, jaundice, and malaise. What is the most likely diagnosis based on the serology reports given below? Anti-HBc (IgM): Positive HBsAg: Positive Anti-HBs: Negative Anti-HCV antibodies: Negative","o":["Acute hepatitis B","Acute hepatitis C","Chronic hepatitis B","Chronic hepatitis C"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000114, '2022', 115, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":115,"q":"A child presents to the emergency department with a history of ingestion of 10-20 ferrous sulphate tablets. Arterial blood gas revealed acidosis. Which of the following can be used in the management of this condition?","o":["Deferoxamine","Activated charcoal","Dimercaprol","Penicillamine"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000115, '2022', 116, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":116,"q":"A photographer who recently returned from Africa presents to the emergency department with abdominal pain, hepatomegaly, and hemorrhagic manifestations. He died despite treatment, and an autopsy revealed intranuclear Torres bodies in the liver. Which of the following vaccines with which strain could have prevented it?","o":["17D","Nakayama vaccine","Weigl’s vaccine","Jeryl Lynn strain"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000116, '2022', 117, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":117,"q":"A militant presents with rashes all over his body sparing the palms and soles. On examination, he was febrile and lice were noted. Which of the following is responsible for his condition?","o":["Rickettsia typhi","Rickettsia prowazekii","Rickettsia akari","Rickettsia conorii"],"a":1,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000117, '2022', 118, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":118,"q":"A patient presents with itching in the axilla. On microscopic examination of the skin scrapings, a red pigment-producing fungus with pencil – shaped macroconidia is seen. Which of the following is the most likely organism?","o":["Trichophyton violaceum","Trichophyton rubrum","Trichophyton tonsurans","Trichophyton schoenleinii"],"a":1,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000118, '2022', 119, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":119,"q":"A female patient presents with complaints of thick white vaginal secretions. Which of the following can be used to identify the likely species of the causative agent?","o":["Birds seed agar","Brain heart infusion agar","CHRO Magar","Sabouraud dextrose agar"],"a":2,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000119, '2022', 120, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":120,"q":"A 12-year-old boy presents with right upper quadrant pain, calf pain, conjunctival suffusion, icterus, and fever. Examination shows tender hepatomegaly. What is the most likely diagnosis?","o":["Chikungunya","Leptospirosis","Dengue hemorrhagic fever","Encephalopathy caused by hepatitis A"],"a":1,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000120, '2022', 121, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":121,"q":"A newly joined teacher develops rice water stools. The causative agent acts on which of the following receptors?","o":["GM 1 ganglioside receptor","GM 2 ganglioside receptor","Sphingomyelin","Cerebroganglioside"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000121, '2022', 122, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":122,"q":"Which of the following is considered to be the best for the detection of Clostridium difficile?","o":["Aerobic culture of stool","Glutamate dehydrogenase and toxin assay","Glutamate dehydrogenase assay","None of the above"],"a":1,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000122, '2022', 123, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":123,"q":"A diabetic truck driver presents to you with cough and breathlessness. A diagnosis of pneumonia was confirmed, and histopathological examination revealed dichotomous branching, as shown below. What is the likely causative agent?","o":["Rhizopus","Mucor","Candida","Aspergillus"],"a":1,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000123, '2022', 124, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":124,"q":"A woman with recurrent diarrhea is prescribed a broad-spectrum antibiotic. Which of the following is not true regarding Clostridium difficile infection?","o":["Oral fidaxomicin is used for treatment","It is toxin mediated","IgM assay is used to confirm the diagnosis","Pseudomembrane is a layer of inflammatory"],"a":2,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000124, '2022', 125, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":125,"q":"An 8-day old newborn was found to have a thyroid – stimulating hormone level of more than 100 mIU/L. Which of the following will be the next best investigation?","o":["Urine iodine excretion","Serum thyroid receptor antibody","Radiotracer uptake with technetium","Perchlorate secretion"],"a":2,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000125, '2022', 126, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":126,"q":"A 10-month old infant was brought with complaints of jerking movement of limbs towards the body. On examination, there is a regression of developmental milestones. Electroencephalogram shows hypsarrhythmia. Which of the following is the drug of choice in this condition ?","o":["Phenytoin","Adrenocorticotropic hormone","Levetiracetam","Phenobarbitone"],"a":1,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000126, '2022', 127, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":127,"q":"A 2-month old infant born to an HIV- positive mother presents with recurrent diarrhea. What is the next best step?","o":["Test stool for giardia and give antibiotics","Dried spot sample for HIV DNA PCR","Antibody test for HIV","Aerobic culture"],"a":1,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000127, '2022', 128, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":128,"q":"An 8-year old child has difficulty walking and getting up from a squatting position. A muscle biopsy was done and is as shown in the image. Which of the following is true about this condition?","o":["Death occurs in 3rd decade","Previous history of viral prodrome","It is a mitochondrial storage disorder","d.Early treatment has excellent prognosis"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":true}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000128, '2022', 129, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":129,"q":"A person after sleeping overnight with the arm under his head now experiences paresis but no numbness in the morning. Which of the following is the best explanation for it?","o":["C fibers are more sensitive to pressure than A fibers","A fibers are more sensitive to hypoxia than B fibers","A fibers are more susceptible to pressure changes than C fibers","A fibers are more susceptible to hypoxia than C fibers"],"a":2,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000129, '2022', 130, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":130,"q":"Which of the following mechanisms is seen in the baroreceptor reflex?","o":["Feedforward","Positive feedback","Negative feedback","Adaptive control regulation"],"a":2,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000130, '2022', 131, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":131,"q":"The image below depicts which of the following types of cell-to-cell signaling?","o":["Paracrine","Autocrine","Endocrine","Merocrine"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":true}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000131, '2022', 132, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":132,"q":"Which of the following statements is true regarding the given cystometrogram?","o":["Segment la is due to residual urine","Segment lb is due to Laplace law","Micturition fails to happen in segment ll","The dotted line represents that micturition has occurred"],"a":1,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
