INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000137, '2022', 138, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":138,"q":"A patient is brought to the casualty following a road traffic accident. On examination, the patient is conscious, BP is 90/60 mm Hg, respiratory rate is 40 breaths per minute, and pulse rate is 120 bpm. The X ray is shown below. What is the next step in management?","o":["Chest tube insertion","Pericardiocentesis","Thoracotomy","Pleurodesis"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000138, '2022', 139, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":139,"q":"A child presented with a history of loose stools with an increase in frequency of 4 days. On examination, he is drowsy, unable to feed, and skin on pinching goes back very slowly. According to the integrated management of neonatal and childhood illness (IMNCI), this child will be classified as having","o":["Mild dehydration","Some dehydration","Severe dehydration","Moderate dehydration"],"a":2,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
