INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000140, '2022', 141, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":141,"q":"A 45-year-old female patient underwent a thyroidectomy. Three days after the surgery, she developed perioral numbness. Which of the following investigations need to be done for her?","o":["Free T3, T4","T3, T4, thyroid–stimulating hormone","Radioiodine scan","Calcium, phosphate, and parathormone levels"],"a":3,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000141, '2022', 142, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":142,"q":"Which of the following children are considered at risk babies ? 1. Baby with a birth weight of 2.5 kg 2. Baby on artificial feeds 3. Baby of working mother / single parent 4. Baby with weight <85% of expected weight 5. Birth order of 3 or more","o":["2,3","1,2,3,4","4,5","1,4"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000142, '2022', 143, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":143,"q":"A patient presented with blunt trauma to the abdomen. On evaluation, liver injury was noted, for which primary repair was done. Coagulation function was monitored intraoperatively, using the method shown below. What is the method used?","o":["Thromboeslastography","Plethysmography","Sonography","Elastography"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
