INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000144, '2022', 145, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":145,"q":"A 59-year-old lady presents with a progressive, painless lump in the breast. What is the cause for the following skin change?","o":["Infiltration of subdermal lymphatics","Infiltration of the lactiferous duct","Involvement of Cooper’s ligament","Spread of the tumor to the anterior chest wall"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000145, '2022', 146, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":146,"q":"A previously healthy child presented with acute – onset dyspnea. A chest X – ray shows unilateral hyperinflation of the lungs. What is true for this patient ?","o":["Focal area of decreased air entry will be suggestive of foreign body","Flexible bronchoscopy used for removal","In complete obstruction ball and valve mechanism causes hyperinflation","The child has developed acute laryngotracheobronchitis"],"a":2,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
