INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000148, '2022', 149, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":149,"q":"Which of the following is most likely to be seen due to the rupture of a saccular aneurysm?","o":["Subdural hemorrhage","Subarachnoid hemorrhage","Intracerebral hemorrhage","Hydrocephalus"],"a":1,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000149, '2022', 150, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":150,"q":"A patient presents with sudden–onset right leg pain. An investigation was done, and the obtained image is shown below. What is the investigation?","o":["A digital subtraction angiography","Ultrasound doppler","MR angiography","Plethysmography"],"a":1,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":true}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000150, '2022', 151, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":151,"q":"A 10 year old presents with edema and anasarca. A diagnosis of minimal change disease is made. Which of the following is true about this condition?","o":["Light microscopy shows effacement of podocytes","Good response to steroids","Most common in adults","Non selective proteinuria"],"a":1,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000151, '2022', 152, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":152,"q":"A male patient presented with a 0.3 cm nodule on the left nasolabial fold. It was excised, and a pathological examination was done. What is the diagnosis?","o":["Basal cell carcinoma","Melanoma","Squamous cell carcinoma","Nevus"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000152, '2022', 153, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":153,"q":"A 10-year old child presents with diarrhea and weight loss. On examination, the height and weight are lesser than expected. Laboratory investigations were positive for class II HLA-DQ2. Which of the following will you advise the child ?","o":["Fat free diet","Lactose free diet","Low carbohydrate diet","Gluten free diet"],"a":3,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000153, '2022', 154, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":154,"q":"A 45- year old patient complained of pain in one side of the neck. She is afraid of eating food as it worsens the pain. Ultrasound imaging of the salivary glands is done and shown below. What is the most likely diagnosis?","o":["Sialolithiasis","Foreign body","Osteoma of the floor of the mouth","Cervical lymphadenopathy"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
