INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000156, '2022', 157, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":157,"q":"A male patient with chronic obstructive pulmonary disease (COPD) was prescribed theophylline. He noticed that his urine output had increased the following day. This action of the drug is mediated through which of the following receptors?","o":[". Interleukin – 10","Histone deacetylase","Adenosine A1","Beta 2 adrenergic receptors"],"a":2,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000157, '2022', 158, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":158,"q":"A male patient presented with midline neck swelling. He later developed cervical node enlargement. The histopathology of the lesion is shown below. Which of the following statements is false about this condition?","o":["Excellent prognosis is associated with this condition","It spreads quickly via lymphatics","Nuclear characteristics are used for the identification","Fine needle aspiration cytology (FNAC) is not diagnostic"],"a":3,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
