INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000159, '2022', 160, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":160,"q":"A 40-year-old man with a known case of hypertension presented with multiple episodes of hematuria and loin pain. His elder brother passed away due to a stroke at the age of 40. The ultrasound abdomen is shown below. What is the probable diagnosis?","o":["Renal cell carcinoma","Autosomal dominant polycystic kidney disease","Tuberculosis of the kidney","Autosomal recessive polycystic kidney disease"],"a":1,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000160, '2022', 161, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":161,"q":"A patient presents with acute–onset, severe abdominal pain. He is hemodynamically stable. A chest X-ray is shown below. What is the next step in management?","o":["Gastric lavage","Chest tube insertion","Tracheostomy","Resuscitation and laparotomy"],"a":3,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000161, '2022', 162, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":162,"q":"A patient with deep vein thrombosis was started on a new drug. After 2 days, he presented with the given finding. Which of the following drugs is implicated in causing the above condition?","o":["Warfarin","Heparin","Dabigatran","Rivarox"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000162, '2022', 163, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":163,"q":"Calculate the percentage of burns in a preschool child shown in the image below","o":["15-20%","25-30%","35-40%","10-15%"],"a":1,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":true}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000163, '2022', 164, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":164,"q":"A patient undergoing chemotherapy was given an antiemetic, after which he developed symptoms like acute dystonia, bradykinesia, and tremors. Which of the following drugs would have caused these symptoms?","o":["Ondansetron","Metoclopramide","Meclizine","Scopolamine"],"a":1,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000164, '2022', 165, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":165,"q":"A young patient started to take a weight loss medication that acts by inhibiting fat absorption from food. After a few weeks, she developed easy bruising and increased menstrual bleeding. Deficiency of which of the following vitamins is responsible for her condition?","o":["Vitamin E","Vitamin K","Vitamin B6","Vitamin D"],"a":1,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000165, '2022', 166, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":166,"q":"A 32-year-old patient who is a chronic alcoholic presents with oral ulcers and a burning sensation. A picture of the oral cavity is given below. What is the most likely diagnosis?","o":["Leukoplakia","Erythroplakia","Submucosal fibrosis","Malakoplakia"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000166, '2022', 167, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":167,"q":"A woman presenting with symptoms of urinary tract infection was prescribed a drug that causes tendon rupture and arthropathy. What is the mechanism of action of the drug?","o":["DNA gyrase inhibition","Ribosomal inhibition","Cell wall synthesis","Inhibition of folic acid synthesis"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000167, '2022', 168, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":168,"q":"A patient presents with a tender pulsatile mass, as shown in the image below. What will be done next for this patient?","o":["Ultrasound doppler","Needle aspiration","CT angiogram with percutaneous management","Intravenous antibiotics for 7 days"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":true}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000168, '2022', 169, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":169,"q":"A patient was brought to the emergency with a history of consumption of 8 tablets of digoxin. On examination he was unstable and his heart rate was 56 bpm. ECG showed a 3rd-degree heart block. What is the next step in the management of this patient?","o":["a.Antibody against digoxin","Lidocaine","c.DC cardioversion","d.Phenytoin"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000169, '2022', 170, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":170,"q":"An elderly man, who is a known case of diabetic nephropathy, presented to the emergency with palpitations and chest discomfort. ECG showed tall T-waves. Laboratory investigations showed elevated potassium levels. Which of the following drugs will cause the shift of potassium back into the cell?","o":["Epinephrine","b.Glucagon","c.Atropine","d.Lactic acid"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000170, '2022', 171, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":171,"q":"A patient with a pituitary tumor that overproduced growth hormone underwent surgical removal of the tumor. The resection was found to be incomplete. What is the first-line treatment for this patient?","o":["Leuprolide","Goserelin","Nafarelin","Octreotide"],"a":3,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000171, '2022', 172, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":172,"q":"A middle-aged male patient presents with protrusion of the chin, excessive sweating, impaired glucose tolerance, and enlargement of hands and feet. Which of the following is a growth hormone receptor antagonist used to treat this condition?","o":["Octreotide","Pegvisomant","Cabergoline","Olcegepant"],"a":1,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000172, '2022', 173, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":173,"q":"A patient presents with prostate carcinoma, which has now spread to the vertebra. What is the route of spread to the lumbar vertebra?","o":["Prostatic venous plexus","Transcoelomic spread","Inferior vesical vein","Internal iliac vein"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000173, '2022', 174, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":174,"q":"A diabetic patient presented with rhinitis and facial swelling. An intranasal biopsy revealed the presence of broad-based aseptate hyphae with branching at right angle. Evidence of vascular invasion was present. What will be the drug of choice for this condition?","o":["Fluconazole","Amphotericin B","Ketoconazole","Griseofulvin"],"a":1,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000174, '2022', 175, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":175,"q":"A male patient presents with impotence and bilateral resting pain. The following finding is seen in the legs. At which level has the pathology occurred?","o":["Bilateral popliteal arteries","Bilateral internal iliac arteries","Aortoiliac bifurcation","Bilateral femoral arteries"],"a":2,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000175, '2022', 176, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":176,"q":"A tuberculosis patient on anti-tubercular treatment presents with a tingling sensation and paresthesia in the lower limbs. He is not a diabetic and occasionally consumes alcohol. Which of the following vitamins must be supplemented to this patient?","o":["Vitamin B6","Vitamin B12","Vitamin B2","Vitamin B3"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000176, '2022', 177, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":177,"q":"An elderly male patient presented with a sudden onset of scrotal pain and discharge. Based on the image below, what is the likely diagnosis?","o":["Torsion of testis","Acute epididymo-orchitis","Scrotal carcinoma","Fournier’s gangrene"],"a":3,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":true}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000177, '2022', 178, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":178,"q":"An elderly woman received a botox injection for the treatment of wrinkles. Which of the following is the mechanism of action of botulinum toxin?","o":["Inhibits the release of acetylcholine","Release of noradrenaline at synaptic cleft","Selectively and irreversibly inhibits nicotinic receptors","Stimulates muscarinic and nicotinic receptors"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000178, '2022', 179, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":179,"q":"Identify the fluid shown below on the basis of composition: Na+ 131mmol/L Cl- 111 mmol/L Lactate 29 mmol/L K+ 5 mmol/L Ca2+ 2 mmol/L Total 279mOsm/L","o":["Haemaccel","Ringer lactate","Isolyte","Isolyte M"],"a":1,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
