INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000184, '2022', 185, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":185,"q":"According to triage, which of the following categories of patients comes under green?","o":["Ambulatory patients","Medium risk patients","High-risk patients","Dead patients"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000185, '2022', 186, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":186,"q":"The average life expectancy for a woman in Japan is 87 years. Due to recent advances in testing for cervical cancer, there is an increase in life expectancy by 15 years. The healthcare utility value is 0.8. Which of the following can be calculated from the parameters given?","o":["HALE","DALY","DFLE","QALY"],"a":3,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000186, '2022', 187, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":187,"q":"You are working in a primary health center (PHC) situated in a high seismic zone. Which of the following will you do as part of preparedness for an emergency? 1. Disaster preparedness by making sure all financial and other resources are available 2. Increase public awareness through campaigns and loudspeakers 3. Conduct a simulation for the disaster and assess the response 4. Follow instructions given over the phone or radio by higher officials","o":["1,2,3,4","2,3,4","1,2,3","1,2,4"],"a":2,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000187, '2022', 188, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":188,"q":"Although many animals are implicated in the spread of rabies, dogs are the most common ones. Also, it usually affects children in developing countries. Knowing this, what is the most cost-effective and logical way to reduce the incidence of rabies?","o":["Testing all the dogs for rabies","Reduce stray dog population and vaccinate all dogs","Increase the laboratory facilities","Increase capacity of healthcare workers for surveillance"],"a":1,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000188, '2022', 189, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":189,"q":"Which of the following steps is not included in the STEP approach of WHO?","o":["Therapeutic assessment","Physical assessment","Psychological assessment","Behavioral assessment"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000189, '2022', 190, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":190,"q":"A male patient diagnosed with tuberculosis took complete treatment. Sputum examination was done after the completion of the intensive and the continuation phases. It was found to be negative. What is the status of the patient?","o":["Cured","Treatment completed","Lost to follow up","Treatment failed"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000190, '2022', 191, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":191,"q":"A cohort study was conducted with drinkers and non-drinkers of green tea to study its effect on diabetes mellitus. The risk ratio was found to be 0.84. Which of the following statements is correct?","o":["Green tea reduces the risk of diabetes","Green tea increases the risk of diabetes","Data insufficient to establish causal association","The value (0.85) tends to be close to 41, hence there is no effect"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000191, '2022', 192, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":192,"q":"Which statement refers best to the criteria for starting an urban community health center?","o":["Caters to a population of 1-1.5 lakh","Referral center for 2-3 primary health centers","No sub-district and district hospitals present in the area","Should have a 100-bed facility in metro cities"],"a":3,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000192, '2022', 193, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":193,"q":"How is a broken vaccine vial disposed of, according to biomedical waste management?","o":["Puncture proof blue bin","White container","Yellow container","Red container"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000193, '2022', 194, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":194,"q":"In an urban area in the state of Madhya Pradesh, a primigravida goes for institutional delivery after being motivated by an ASHA worker. What are the benefits they will receive (in terms of money in rupees) under the Janani Suraksha Yojana? ASHA-Accredited social health activist","o":["1000 for mother and 400 for ASHA","1400 for mother and 600 for ASHA","600 for mother and 400 for ASHA","400 for mother and 600 for ASHA"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000194, '2022', 195, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":195,"q":"Which of the following agencies provides seed and manure in applied nutrition programs in schools?","o":["CARE","UNDP","UNICEF","WHO"],"a":2,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000195, '2022', 196, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":196,"q":"Many children from a particular community coming to a hospital were detected to have acute lymphoblastic leukemia (ALL). It was assumed that it is due to the presence of cytotoxic waste in the water of that community. If a case-control study has to be done to find whether the chemical and ALL are associated, what will be taken as the control?","o":["Children from the area exposed, but unaffected with the disease","Children from the area not exposed and affected with the disease","Children coming to your OPD, who do not have the disease","All children with ALL irrespective of exposure status"],"a":0,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000196, '2022', 197, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":197,"q":"A patient presents with an anesthetic patch in the areas on the face, as shown in the image below. Which of the following nerves is the most commonly involved in this condition?","o":["Abducens nuclei","Facial nerve","Optic nerve","Trigeminal nerve"],"a":1,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":true}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000197, '2022', 198, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":198,"q":"An auxiliary nurse midwife has to conduct a vaccination camp in a village. She received 2 open vials, one of which is a pentavalent vaccine and the other is an MR vaccine. What can she do regarding the utilization of these vials?","o":["Use MR vaccine and discard pentavalent vaccine","Use both","Use pentavalent vaccine and discard MR vaccine","Discard both"],"a":2,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000198, '2022', 199, NULL, 'NEET-PG-2022-Question-Paper-With-Solutions.pdf', '{"no":199,"q":"A female patient with a body mass index of 30 kg/m2 presents to you with a lesion on the neck, as shown below. Which of the following conditions is the most likely to be suffering from?","o":["Hypothyroidism","Metabolic syndrome","Addision’s disease","Hyperparathyroidism"],"a":1,"year":"2022","paper":"2022","source_file":"NEET-PG-2022-Question-Paper-With-Solutions.pdf","image_based":false}');
