INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000202, '2024', 3, NULL, '2024 Shift 1 solution.pdf', '{"no":3,"q":"What is the most likely diagnosis for the lesion shown here?","o":["Sunburst appearance","Onion-skin appearance","Codman’s triangle","Ground glass appearance"],"a":0,"year":"2024","paper":"2024 Shift 1","source_file":"2024 Shift 1 solution.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000203, '2024', 4, NULL, '2024 Shift 1 solution.pdf', '{"no":4,"q":"Lesion Characteristics: Evaluate whether the lesion is macular (flat), papular (raised), nodular (solid), or vesicular (fluid-filled), and check for additional features like ulceration or scaling. Page 4 of 184 2. Color Analysis: Determine if the lesion is hyperpigmented, hypopigmented, erythematous (red), or has other distinct colorations which are often indicative of specific conditions. 3. Pattern Recognition: Identifying common patterns such as annular (ring- shaped), linear, or grouped lesions can aid in pinpointing common dermatological diagnoses like fungal infections or psoriasis. 4. Location Considerations: Where on the body the lesion is located. Some conditions have a predilection for specific body parts, like psoriasis on extensor surfaces or seborrheic dermatitis affecting the scalp and face. 5. Patient History: Consider any recent exposure to allergens, infections, or trauma. Medical history such as immune status or family history can also provide important diagnostic clues. 6. Symptom Analysis: Determine if the lesion is symptomatic (itching, pain) or asymptomatic; some lesions like basal cell carcinoma are notorious for being painless, while others like dermatitis are itchy. Without specific options or an image, a definitive diagnosis cannot be made. However, by assimilating these steps, similar phenomena in different cases can usually be categorized quickly and accurately. Quick Tip: The sunburst pattern is often seen in aggressive bone tumors like osteosarcoma and is a key diagnostic feature on radiographs. 4. A patient from a railway station is arrested by police and shows symptoms like dilated pupils, sweating, hot skin, and staggering gait. He is suspected to have intoxication from:","o":["Dhatura","Cocaine","Alcohol","Morphine"],"a":0,"year":"2024","paper":"2024 Shift 1","source_file":"2024 Shift 1 solution.pdf","image_based":true}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000204, '2024', 5, NULL, '2024 Shift 1 solution.pdf', '{"no":5,"q":"In MTP at 28 weeks for congenital anomalies, whose presence is not required? Page 6 of 184","o":["Obstetrician","Lawyer","Pediatrician","Sonologist"],"a":1,"year":"2024","paper":"2024 Shift 1","source_file":"2024 Shift 1 solution.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000205, '2024', 6, NULL, '2024 Shift 1 solution.pdf', '{"no":6,"q":"A child was born after the death of his father, and some of them claimed that the child is not from his biological father. DNA fingerprinting was done to identify the father, and the deceased father was found to be the biological father. This child is called as:","o":["Posthumous child","Suppositious child","Illegitimate child"],"a":0,"year":"2024","paper":"2024 Shift 1","source_file":"2024 Shift 1 solution.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000206, '2024', 7, NULL, '2024 Shift 1 solution.pdf', '{"no":7,"q":"Which one is correct about the sequence of rigor mortis?","o":["Centre to periphery","Head to foot","Foot to head","Simultaneously"],"a":1,"year":"2024","paper":"2024 Shift 1","source_file":"2024 Shift 1 solution.pdf","image_based":false}');
