INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000210, '2024', 11, NULL, '2024 Shift 1 solution.pdf', '{"no":11,"q":"A 12-year-old child presented with sudden severe onset of scrotal pain after a history of trauma 6 hours before. Intraoperative image is given. What is the likely diagnosis?","o":["Torsion testis with gangrene","Testicular hematoma","Torsion testis","Gangrene of testis"],"a":0,"year":"2024","paper":"2024 Shift 1","source_file":"2024 Shift 1 solution.pdf","image_based":true}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000211, '2024', 12, NULL, '2024 Shift 1 solution.pdf', '{"no":12,"q":"What is the negative pressure in VAC dressing?","o":["60-90 mmHg","90-100 mmHg","120-130 mmHg","130-150 mmHg"],"a":2,"year":"2024","paper":"2024 Shift 1","source_file":"2024 Shift 1 solution.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000212, '2024', 13, NULL, '2024 Shift 1 solution.pdf', '{"no":13,"q":"Identify the structure marked in the intraoperative image of congenital inguinal hernia:","o":["Femoral vein","Obturator vein","Testicular vein","Inferior epigastric vein"],"a":2,"year":"2024","paper":"2024 Shift 1","source_file":"2024 Shift 1 solution.pdf","image_based":true}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000213, '2024', 14, NULL, '2024 Shift 1 solution.pdf', '{"no":14,"q":"Femoral Vein: The femoral vein runs through the femoral sheath alongside the femoral artery and nerve. It is located beneath the inguinal ligament and lateral to the femoral canal, making it an unlikely candidate in this context. 2. Obturator Vein: Situated within the pelvis, the obturator vein drains into the internal iliac vein. It is not typically involved in the anatomy of a congenital inguinal hernia. 3. Testicular Vein: Arising from the pampiniform plexus, the testicular vein is located in the spermatic cord, which is found within the inguinal canal involved in an inguinal hernia. This makes it the most relevant structure in this context. 4. Inferior Epigastric Vein: This vein travels superiorly from the external iliac vein and is associated with the anterior abdominal wall, rather than the structures commonly seen in a congenital inguinal hernia repair. The structure visible in the image associated with the inguinal canal and spermatic cord is therefore identified as the Testicular Vein. Quick Tip: The testicular vein should be identified and preserved during the repair of a congenital inguinal hernia to prevent damage to the venous drainage of the testes. Page 14 of 184 14. How does a skin graft derive its nutrition on day 3?","o":["Plasma imbibition","Inosculation","Neovascularization","None"],"a":1,"year":"2024","paper":"2024 Shift 1","source_file":"2024 Shift 1 solution.pdf","image_based":true}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000214, '2024', 15, NULL, '2024 Shift 1 solution.pdf', '{"no":15,"q":"Identify the ulcer:","o":["Arterial","Venous","Trophic","Diabetic foot ulcer"],"a":1,"year":"2024","paper":"2024 Shift 1","source_file":"2024 Shift 1 solution.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000215, '2024', 16, NULL, '2024 Shift 1 solution.pdf', '{"no":16,"q":"A 30-year-old female presented with swelling in the neck. What is the next step in evaluation?","o":["I131","FNAC","TSI & T4","FSH"],"a":2,"year":"2024","paper":"2024 Shift 1","source_file":"2024 Shift 1 solution.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000216, '2024', 17, NULL, '2024 Shift 1 solution.pdf', '{"no":17,"q":"I131: This is a radioactive iodine uptake test primarily used to assess thyroid function and diagnose hyperthyroidism. However, it is not the first-line test for evaluating neck swelling. 2. FNAC (Fine Needle Aspiration Cytology): This procedure helps in obtaining tissue samples for cytological examination and is usually recommended when there is suspicion of a thyroid nodule or malignancy. 3. TSI & T4: These are blood tests measuring Thyroid Stimulating Immunoglobulin (TSI) and thyroxine (T4), respectively. TSI is particularly useful in evaluating autoimmune thyroid conditions (e.g., Graves'' disease), while T4 levels indicate overall thyroid function. It helps in assessing thyroid gland activity in cases of swelling, potentially due to hyperthyroidism. 4. FSH (Follicle Stimulating Hormone): This is related to reproductive health and is not relevant to assessing thyroid-related neck swelling. Considering the options, the most pertinent step for evaluating neck swelling of likely thyroid origin is to perform blood tests to check for thyroid function and autoimmunity. Therefore, the next step should be measuring TSI & T4 levels to gain insight into the thyroid''s activity and possible autoimmune involvement. Quick Tip: Measuring thyroid hormones (TSH, T3, T4) is crucial for diagnosing thyroid disorders in patients with neck swelling. 17. A 5-year-old girl was washing her doll with shampoo containing a chemical Rotenone. Her mother notices her in an unconscious state. Which of the following complex is inhibited by the above-mentioned chemical?","o":["NADH Dehydrogenase","Succinate DH","Cytochrome C","Cytochrome oxidase"],"a":0,"year":"2024","paper":"2024 Shift 1","source_file":"2024 Shift 1 solution.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000217, '2024', 18, NULL, '2024 Shift 1 solution.pdf', '{"no":18,"q":"NADH Dehydrogenase (Complex I): This complex is the first entry point for electrons from NADH. Rotenone inhibits this complex, preventing NADH from donating electrons. 2. Succinate DH (Complex II): This complex oxidizes succinate to fumarate, facilitating electron transfer from FADH2. 3. Cytochrome C: This is a small protein that transfers electrons between Complexes III and IV. 4. Cytochrome oxidase (Complex IV): This complex transfers electrons to oxygen, the final electron acceptor, reducing it to water. Given that Rotenone specifically inhibits the transfer of electrons from NADH to the ubiquinone in Complex I, the inhibited complex is NADH Dehydrogenase. Quick Tip: Rotenone inhibits NADH dehydrogenase, disrupting ATP production and leading to cellular dysfunction and toxicity. Page 19 of 184 18. Which of the following is true regarding the image provided?","o":["EMLA contains ropivacaine and ligocaine.","EMLA can lead to hemoglobinemia.","EMLA contains 5 percent lignocaine.","EMLA acts within 15 minutes."],"a":1,"year":"2024","paper":"2024 Shift 1","source_file":"2024 Shift 1 solution.pdf","image_based":true}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000218, '2024', 19, NULL, '2024 Shift 1 solution.pdf', '{"no":19,"q":"A patient presents with no pulse, and the ECG shows the following rhythm. What is the next appropriate step?","o":["Defibrillate, check pulse and then perform CPR","Cardioversion","Defibrillate, perform CPR, and then check the pulse","Administer epinephrine"],"a":2,"year":"2024","paper":"2024 Shift 1","source_file":"2024 Shift 1 solution.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000219, '2024', 20, NULL, '2024 Shift 1 solution.pdf', '{"no":20,"q":"Recognize the Situation: The absence of a pulse combined with a shockable rhythm on the ECG (such as ventricular fibrillation or pulseless ventricular tachycardia) indicates the need for immediate intervention. 2. Immediate Action: Defibrillation should be performed as soon as possible. This is critical in the case of shockable rhythms to restore a normal heart rhythm. 3. Perform CPR: After delivering a shock, immediately start Cardiopulmonary Resuscitation (CPR). Continue CPR for two minutes before reassessing the patient. 4. Check the Pulse: After two minutes of CPR, pause to check the patient''s pulse and rhythm. The answer highlighted reflects these crucial steps: \"Defibrillate, perform CPR, and then check the pulse.\" Quick Tip: In the case of ventricular fibrillation, defibrillation followed by CPR is the most effective initial management to restore circulation and save the patientâ€™s life. 20. Identify the arrow-marked nerve.","o":["Medial pectoral nerve","Lateral pectoral nerve","Long thoracic nerve","Thoracodorsal nerve"],"a":0,"year":"2024","paper":"2024 Shift 1","source_file":"2024 Shift 1 solution.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000220, '2024', 21, NULL, '2024 Shift 1 solution.pdf', '{"no":21,"q":"Medial pectoral nerve 2. Lateral pectoral nerve 3. Long thoracic nerve 4. Thoracodorsal nerve To identify the correct nerve, let''s consider the anatomical features and typical locations of each nerve: Medial Pectoral Nerve: Usually innervates the pectoralis minor and major muscles. It passes through or near the lateral thoracic wall. Lateral Pectoral Nerve: Primarily innervates the pectoralis major. It often communicates with the medial pectoral nerve. Long Thoracic Nerve: Innervates the serratus anterior muscle, and is located on the lateral thoracic wall, running along or near the rib cage. Thoracodorsal Nerve: Innervates the latissimus dorsi muscle. Typically found running in the axillary region. The correct nerve, as indicated by the provided options, is the Medial Pectoral Nerve. This assessment is based on the typical anatomical pathway and innervation characteristics of the listed nerves relevant to the context. Quick Tip: In neuroanatomy, it is important to familiarize yourself with the origins and functions of the various peripheral nerves, especially their anatomical landmarks. 21. Behind the medial malleolus and in front of Achilles, which artery is present? Page 23 of 184","o":["Posterior tibial artery","Peroneal artery","Anterior tibial artery","Dorsalis pedis artery"],"a":0,"year":"2024","paper":"2024 Shift 1","source_file":"2024 Shift 1 solution.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000221, '2024', 22, NULL, '2024 Shift 1 solution.pdf', '{"no":22,"q":"The covering of an omphalocele is derived from which layer?","o":["Amnion","Chorion","Mesoderm","Endoderm"],"a":0,"year":"2024","paper":"2024 Shift 1","source_file":"2024 Shift 1 solution.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000222, '2024', 23, NULL, '2024 Shift 1 solution.pdf', '{"no":23,"q":"A 13-year-old boy presents with jaundice, fatigue, muscle stiffness, tremors, behavioral changes, hepatosplenomegaly, and Kayser-Fleischer rings. Which test is definitive for the diagnosis?","o":["Urinary copper","Serum ceruloplasmin","Hepatic parenchymal copper concentration","Genetic testing for ATP7B mutation"],"a":1,"year":"2024","paper":"2024 Shift 1","source_file":"2024 Shift 1 solution.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000223, '2024', 24, NULL, '2024 Shift 1 solution.pdf', '{"no":24,"q":"A patient presents with xanthomas on the Achilles tendon. Which of the following is the most likely diagnosis?","o":["Familial hypercholesterolemia","Tangier disease","Familial hyperchylomicronemia","Type III hyperlipoproteinemia"],"a":0,"year":"2024","paper":"2024 Shift 1","source_file":"2024 Shift 1 solution.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000224, '2024', 25, NULL, '2024 Shift 1 solution.pdf', '{"no":25,"q":"A patient with multiple tendon xanthomas is found to have a serum cholesterol level of 398 mg/dL and an LDL level of 220 mg/dL. What is the most likely defect?","o":["Lipoprotein lipase deficiency","LDL receptor defect","Defective Apo B-100","PCSK9 gain-of-function mutation"],"a":1,"year":"2024","paper":"2024 Shift 1","source_file":"2024 Shift 1 solution.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000225, '2024', 26, NULL, '2024 Shift 1 solution.pdf', '{"no":26,"q":"Lipoprotein lipase deficiency: This condition leads to hypertriglyceridemia, not hypercholesterolemia. It would result in elevated chylomicrons and VLDL rather than LDL. 2. LDL receptor defect: This is the most common cause of familial hypercholesterolemia. It results in elevated LDL levels because LDL particles Page 28 of 184 can''t be taken up by the liver effectively, hence the buildup in the bloodstream. 3. Defective Apo B-100: While this could also cause elevated LDL, it typically presents less severely than an LDL receptor defect and is less common. 4. PCSK9 gain-of-function mutation: This would increase LDL levels but is less common than an LDL receptor defect. Plus, the presence of tendon xanthomas strongly points toward familial hypercholesterolemia due to an LDL receptor defect. Given these considerations, the LDL receptor defect is the most likely cause of the observed symptoms in this patient. Quick Tip: In cases of familial hypercholesterolemia, look for tendon xanthomas and significantly elevated LDL levels. The defect usually lies in the LDL receptor. 26. A 30-year-old patient presents with a history of flat lesions near the anal canal, rashes on the body, and hair loss that follows a particular pattern, as shown in the image. What is the diagnosis?","o":["Trichotillomania","Alopecia areata","Secondary syphilis","Malassezia"],"a":2,"year":"2024","paper":"2024 Shift 1","source_file":"2024 Shift 1 solution.pdf","image_based":true}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000226, '2024', 27, NULL, '2024 Shift 1 solution.pdf', '{"no":27,"q":"A 38-year-old patient with hypopigmented nodular lesions with anesthesia overarm with ulnar nerve involvement underwent a biopsy and intradermal antigen test. Based on the image, which statement regarding the condition is most accurate?","o":["Tuberculoid leprosy with a positive antigen test","Lepromatous leprosy with a positive antigen test","Erythema nodosum leprosum with a negative antigen test","Lepromatous leprosy with a negative antigen test"],"a":3,"year":"2024","paper":"2024 Shift 1","source_file":"2024 Shift 1 solution.pdf","image_based":true}');
