INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000228, '2024', 29, NULL, '2024 Shift 1 solution.pdf', '{"no":29,"q":"A 45-year-old woman is diagnosed with right vestibular neuritis. What findings are expected during the head impulse test in this patient?","o":["When the head is turned to the left, the eyeballs move to the left with Nystagmus.","When the head is turned to the left, the eyeballs move to the right with","When the head is turned to the right, the eyeballs move to the left with","When the head is turned to the right, the eyeballs move to the right with"],"a":2,"year":"2024","paper":"2024 Shift 1","source_file":"2024 Shift 1 solution.pdf","image_based":false}');
