INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000242, '2024', 43, NULL, '2024 Shift 1 solution.pdf', '{"no":43,"q":"A 23-year-old female with a height of 4 feet has a karyotype, as shown in the image below. Which of the following conditions is the most likely etiology?","o":["Turner syndrome","Klinefelter syndrome","Mayer-Rokitansky-KÃ¼ster-Hauser syndrome (MRKHS)","Edwards syndrome"],"a":0,"year":"2024","paper":"2024 Shift 1","source_file":"2024 Shift 1 solution.pdf","image_based":true}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000243, '2024', 44, NULL, '2024 Shift 1 solution.pdf', '{"no":44,"q":"An infant presents with vomiting after feeding. A Benedictâ€™s test was performed and returned positive for a non-glucose substance. Which of the following is the most likely diagnosis?","o":["Galactosemia due to GAL-1-P uridyl transferase enzyme deficiency","Hereditary fructose intolerance due to aldolase B deficiency","Glucose-6-Phosphate dehydrogenase (G6PD) deficiency","Galactosemia due to galactokinase enzyme deficiency"],"a":0,"year":"2024","paper":"2024 Shift 1","source_file":"2024 Shift 1 solution.pdf","image_based":false}');
