INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000248, '2024', 49, NULL, '2024 Shift 1 solution.pdf', '{"no":49,"q":"Which ion is most responsible for the resting membrane potential (RMP)?","o":["Potassium (K+)","Calcium (Ca2+)","Sodium (Na+)","Chloride (Cl-)"],"a":0,"year":"2024","paper":"2024 Shift 1","source_file":"2024 Shift 1 solution.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000249, '2024', 50, NULL, '2024 Shift 1 solution.pdf', '{"no":50,"q":"Concentration Gradient: There is a higher concentration of K+ inside the cell compared to outside. This concentration gradient drives the efflux of K+ out of the cell. 2. Membrane Permeability: The cell membrane is more permeable to K+ than to other ions such as Na+, Ca2+, or Cl-. This is due to the presence of potassium channels that allow K+ to move more freely across the membrane. 3. Electrochemical Gradient: As K+ leaves the cell, it creates a negative charge inside the cell relative to the outside. This electrical gradient opposes the further efflux of K+, stabilizing the RMP. Page 59 of 184 Therefore, due to these factors, potassium (K+) plays the most significant role in establishing and maintaining the resting membrane potential. Conclusion: Potassium (K+) is the ion most responsible for the resting membrane potential (RMP). Quick Tip: The resting membrane potential (RMP) is primarily maintained by potassium (K+) ions, with the Na+/K+ ATPase pump helping to maintain the ion gradient. 50. A fruit farmer presents with fever, respiratory difficulties, and neurological complications. What is the most likely diagnosis?","o":["Ebola","Meningitis","Nipah","Zika"],"a":2,"year":"2024","paper":"2024 Shift 1","source_file":"2024 Shift 1 solution.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000250, '2024', 51, NULL, '2024 Shift 1 solution.pdf', '{"no":51,"q":"Which of the following vaccines is kept at the lowest level? Page 61 of 184","o":["OPV","DPT","Hep B","Rota"],"a":0,"year":"2024","paper":"2024 Shift 1","source_file":"2024 Shift 1 solution.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000251, '2024', 52, NULL, '2024 Shift 1 solution.pdf', '{"no":52,"q":"Which drug is used in the maintenance phase of opioid withdrawal? Page 62 of 184","o":["Buprenorphine","Disulfiram","Butorphanol","Clonidine"],"a":0,"year":"2024","paper":"2024 Shift 1","source_file":"2024 Shift 1 solution.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000252, '2024', 53, NULL, '2024 Shift 1 solution.pdf', '{"no":53,"q":"A 45-year-old woman presents with a long-standing history of â€œfeeling tensedâ€ along with an upset stomach, diarrhea, and heartburn. She mentions that her family members also experience similar symptoms. Which of the following symptoms is most likely to be observed in this patient?","o":["Neologisms","Tingling at extremities","Hallucinations","Idea of reference"],"a":1,"year":"2024","paper":"2024 Shift 1","source_file":"2024 Shift 1 solution.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000253, '2024', 54, NULL, '2024 Shift 1 solution.pdf', '{"no":54,"q":"A 40-year-old female patient complains of a persistent headache. A CT scan of the head was performed, as shown below. What is the most accurate diagnosis?","o":["Subarachnoid hemorrhage (SAH)","Epidural hemorrhage","Subdural hemorrhage","Intraparenchymal hemorrhage"],"a":0,"year":"2024","paper":"2024 Shift 1","source_file":"2024 Shift 1 solution.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000254, '2024', 55, NULL, '2024 Shift 1 solution.pdf', '{"no":55,"q":"Review of Symptoms: The patient reports a persistent headache. A sudden onset severe headache, often described as the \"worst headache of my life,\" is characteristic of SAH. 2. CT Scan Analysis: On the non-contrast CT scan of the head, look for hyperdense areas indicating blood accumulation. In SAH, this typically appears in the basal cisterns, Sylvian fissures, and interhemispheric fissures. 3. Diagnosis Correlation: Compare the CT findings with common patterns seen in other hemorrhages: Subarachnoid hemorrhage: bleeding in the subarachnoid space. Epidural hemorrhage: biconvex (lens-shaped) hyperdensity often seen with skull fracture. Subdural hemorrhage: crescent-shaped hyperdensity that might extend across suture lines. Page 65 of 184 Intraparenchymal hemorrhage: bleeding in the brain parenchyma itself. 4. Final Verification: The CT scan''s hyperdense appearance in the subarachnoid region, along with the clinical presentation of a severe headache, confirms subarachnoid hemorrhage as the most accurate diagnosis. The answer is Subarachnoid hemorrhage (SAH). Immediate neuroimaging and expert consultation are crucial for appropriate management and treatment of SAH. Quick Tip: In a patient with sudden severe headache, a subarachnoid hemorrhage (SAH) should be suspected, especially if blood is seen in the subarachnoid space on a CT scan. 55. A 45-year-old patient presents with ptosis and muscle weakness that improves with rest. She also complains of dysphagia and has engorged veins in her thorax. Based on the CT scan image provided, what is the most likely diagnosis?","o":["Thymoma","Pancoast tumor","Adenocarcinoma","Small cell lung cancer"],"a":0,"year":"2024","paper":"2024 Shift 1","source_file":"2024 Shift 1 solution.pdf","image_based":true}');
