INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000335, '2024', 136, NULL, '2024 Shift 1 solution.pdf', '{"no":136,"q":"A 22 weeks of gestation unmarried 14-year-old girl, who is rape victim comes at your clinic medical termination. What is true for medical abortion?","o":["MTP can be done in rape victim till 24 wks.","Only one Doctor opinion required","Only done if risk of life","MTP can be done after permission of medical board"],"a":0,"year":"2024","paper":"2024 Shift 1","source_file":"2024 Shift 1 solution.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000336, '2024', 137, NULL, '2024 Shift 1 solution.pdf', '{"no":137,"q":"We must apply it to a 14-year-old, unmarried, rape-victim girl at 22 weeks of gestation. (The page does not print an answer key for this item, so the correct option is derived from the current MTP rules.) Step 2: Apply the gestational limits. Under the MTP (Amendment) Act 2021, the upper gestational limit is raised to 24 weeks for special categories of women, which explicitly include survivors of rape/sexual assault and minors. A 14- year-old rape victim therefore falls squarely in the category for whom MTP is lawfully permitted up to 24 weeks. Hence option A – ''MTP can be done in rape victim till 24 wks'' – is the correct, legally accurate statement. Step 3: Examine the other options. • ''Only one Doctor opinion required'' (B): For pregnancies BETWEEN 20 and 24 weeks (as here, 22 weeks) the opinion of TWO registered medical Page 175 of 184 practitioners is required (one RMP suffices only up to 20 weeks). So B is FALSE for a 22-week pregnancy. • ''Only done if risk of life'' (C): This is too restrictive; MTP for a rape victim is permitted on the recognised grounds (grave injury to mental health, pregnancy from rape is presumed to constitute grave mental injury) and is NOT limited to risk to life alone. So C is FALSE. • ''MTP can be done after permission of medical board'' (D): A Medical Board''s approval is required ONLY for termination BEYOND 24 weeks (in cases of substantial fetal abnormality). At 22 weeks a Medical Board is not the prerequisite. So D is FALSE for this gestation. Step 4: Conclude. The legally true statement for this 14-year-old rape survivor at 22 weeks is that MTP can be carried out in a rape victim up to 24 weeks. Final answer: A – MTP can be done in rape victim till 24 wks. Quick Tip: Under the MTP Amendment Act 2021, rape survivors and minors get an extended 24-week limit – but 20–24 weeks needs two RMPs, and a Medical Board is only for beyond 24 weeks. 137. This is seen in postmortem examination of which type of asphyxia:","o":["Throttling","Smothering","Hanging","Garrotting"],"a":1,"year":"2024","paper":"2024 Shift 1","source_file":"2024 Shift 1 solution.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000337, '2024', 138, NULL, '2024 Shift 1 solution.pdf', '{"no":138,"q":"A G5P4 woman comes for routine sonography for the first time, she has early four daughters and wants to have a boy this time and asks for sex determination. To abide by the above depicted guidelines, what will you choose:","o":["Will check routine ANC and sex for developmental ABN and do not reveal gender","Will check routine ANC and sex for developmental ABN and do reveal gender to","Do reveal gender if a girl","Check only routine ANC, do not check sex"],"a":0,"year":"2024","paper":"2024 Shift 1","source_file":"2024 Shift 1 solution.pdf","image_based":false}');
