INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000412, '2025', 44, NULL, 'Solution 2025.pdf', '{"no":44,"q":"A young adult presents with facial pain and painful vesicular lesions in the mouth. Tzanck smear reveals multinucleated giant cells with intranuclear inclusions. What is the most likely causative organism?","o":["Adenovirus","Cytomegalovirus","EBV","HSV"],"a":3,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000413, '2025', 45, NULL, 'Solution 2025.pdf', '{"no":45,"q":"What is the most common cause for squamous cell carcinoma at the base of the tongue?","o":["EBV","HPV","HCV","CMV"],"a":1,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000414, '2025', 46, NULL, 'Solution 2025.pdf', '{"no":46,"q":"A patient presents with irregular swelling over the foot, multiple discharging sinuses, and black granules. A KOH mount is performed on the discharge. What is the most likely observation? NEET PG 2025 Page 38 of 175 © Collegedunia.com","o":["Arthrospores","Slender dematiaceous fungi","Yeast","Septate hyphae"],"a":3,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000415, '2025', 47, NULL, 'Solution 2025.pdf', '{"no":47,"q":"A 45-year-old patient presents with a chronic granulomatous skin lesion. What is the most confirmatory diagnostic test for this condition? NEET PG 2025 Page 39 of 175 © Collegedunia.com","o":["PCR (Polymerase Chain Reaction)","Slit skin smear","Mantoux test","Skin biopsy with histopathology"],"a":0,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000416, '2025', 48, NULL, 'Solution 2025.pdf', '{"no":48,"q":"A 20-year-old patient presents with a non-progressive hypopigmented lesion on the trunk. On Wood’s lamp examination, there is white accentuation. Diascopy is negative. What is the most likely diagnosis?","o":["Vitiligo","Nevus depigmentosus","Nevus anemicus","Indeterminate leprosy"],"a":1,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000417, '2025', 49, NULL, 'Solution 2025.pdf', '{"no":49,"q":"A patient with intensely itchy vesicular lesions on the extensor surface presents with history of gluten sensitivity. What is the likely diagnosis?","o":["Bullous pemphigoid","Pemphigus vulgaris","Dermatitis herpetiformis","Psoriasis"],"a":2,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000418, '2025', 50, NULL, 'Solution 2025.pdf', '{"no":50,"q":"A patient presents with the injury shown in lateral X-ray of nose. What procedure can be done to manage this patient?","o":["Tilley’s probe","Luc’s forceps","Denis Browne probe","Walsham’s forceps"],"a":3,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000419, '2025', 51, NULL, 'Solution 2025.pdf', '{"no":51,"q":"A 78-year-old male, known case of diabetes mellitus and hypertension presents with nasal bleeding. Initial management such as packing was not successful in controlling the bleed. Which artery should be ligated to control the bleeding?","o":["Sphenopalatine artery","Anterior ethmoidal artery","Posterior ethmoidal artery","Greater palatine artery"],"a":0,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000420, '2025', 52, NULL, 'Solution 2025.pdf', '{"no":52,"q":"A 16-year-old male presents with recurrent profuse nasal bleeding in the right nasal cavity. Endoscopy shows a globular mass in the right nasal cavity. CT shows bowing of the posterior wall of maxillary sinus. What is the most probable diagnosis?","o":["Juvenile Nasopharyngeal Angiofibroma (JNA)","Antrochoanal polyp","Rhinosporidiosis","Rhinoscleroma"],"a":0,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000421, '2025', 53, NULL, 'Solution 2025.pdf', '{"no":53,"q":"What is the marked structure? NEET PG 2025 Page 44 of 175 © Collegedunia.com","o":["Thyroid cartilage","Pyriform sinus","Epiglottis","Vallecula"],"a":1,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000422, '2025', 54, NULL, 'Solution 2025.pdf', '{"no":54,"q":"A 27-year-old male presents with recurrent ear infection. Otoscopic examination shows central perforation of tympanic membrane. Tuning fork examination reveals: Rinne negative on left and positive on right; Weber lateralization to left. What is the type and localization of hearing loss? NEET PG 2025 Page 45 of 175 © Collegedunia.com","o":["Left sensorineural hearing loss","Right sensorineural hearing loss","Left conductive hearing loss","Right conductive hearing loss"],"a":2,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000423, '2025', 55, NULL, 'Solution 2025.pdf', '{"no":55,"q":"A 75-year-old male smoker presents with hoarseness of voice and difficulty in swallowing. He has been diagnosed with large advanced SCC and undergoes surgery. What is the most appropriate surgical procedure?","o":["Total laryngectomy","Partial laryngectomy","Percutaneous tracheostomy","Standard tracheostomy"],"a":0,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000424, '2025', 56, NULL, 'Solution 2025.pdf', '{"no":56,"q":"A 20-year-old patient presents with recurrent ear discharge. On otoscopic examination, the examiner notes complete absence of tympanic membrane. What is the best option for treatment?","o":["Myringoplasty","Radical mastoidectomy","Ossiculoplasty","Tympanoplasty"],"a":3,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000425, '2025', 57, NULL, 'Solution 2025.pdf', '{"no":57,"q":"A 27-year-old male presents with reduced hearing in the left ear for 2 months. He denies tinnitus or vertigo. Pure tone audiometry is done, and the audiogram is shown. Which of the following is the most likely diagnosis?","o":["Left ear SNHL","Left ear CHL","Right ear mixed hearing loss","Normal hearing"],"a":1,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000426, '2025', 58, NULL, 'Solution 2025.pdf', '{"no":58,"q":"During an autopsy of a 35-year-old female, bruises are noted below the right angle of jaw with scratches over the upper border and grouped bruises on the left side of neck below thyroid cartilage, with additional bruises over shoulder blade, back of trunk and hip crests. What is the most likely cause of death?","o":["Throttling","Garroting","Mugging","Ligature strangulation"],"a":0,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000427, '2025', 59, NULL, 'Solution 2025.pdf', '{"no":59,"q":"A 16-year-old girl and a 23-year-old man are medically examined after the girl’s parents accuse the man of rape. The girl reports that the sexual activity was consensual, and no physical injuries are noted. According to law, which statement is correct?","o":["Consent is invalid as the girl is under 18 years","No punishment since the act was consensual","Parents must prove that the act was non-consensual","No punishment since there are no injuries"],"a":0,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000428, '2025', 60, NULL, 'Solution 2025.pdf', '{"no":60,"q":"What is ZASKO’s phenomenon?","o":["Tendon reflex occurring after death","Blood clotting after death","Gaping of wound along skin tension lines","Seeping of blood through bones after death"],"a":0,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000429, '2025', 61, NULL, 'Solution 2025.pdf', '{"no":61,"q":"Under the POCSO Act 2012, which group is protected by the law?","o":["All children under 16 years of age","All children under 18 years of age","Girls under 16 years of age","Girls under 18 years of age"],"a":1,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000430, '2025', 62, NULL, 'Solution 2025.pdf', '{"no":62,"q":"A male patient with recent history of RTA was brought to hospital. His CT scan was normal, but he died within three hours of admission. Autopsy revealed retraction ball appearance and petechial hemorrhages in the corpus callosum. What is the most likely diagnosis?","o":["Diffuse vascular injury","Diffuse axonal injury","Intracerebral hemorrhage","None of the above"],"a":1,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000431, '2025', 63, NULL, 'Solution 2025.pdf', '{"no":63,"q":"A 68-year-old female has breathlessness, poor health status and multiple metastases. She is awake and anxious. Doctors believe aggressive chemotherapy, radiotherapy and ICU admission will not help, but her daughter insists on trying everything. How should the doctor handle this scenario?","o":["Convene to family members and consider the patient’s needs","Shift to ICU and start aggressive treatment","Discharge the patient and shift to palliative care","Give placebo care to relieve anxiety"],"a":0,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000432, '2025', 64, NULL, 'Solution 2025.pdf', '{"no":64,"q":"A 65-year-old patient with history of atrial flutter is being considered for long-term prophylaxis to prevent recurrence. The cardiologist decides to start a calcium channel blocker for rate control and prevention of rapid ventricular response. Which calcium channel blocker is most appropriate?","o":["Amlodipine","Nifedipine","Diltiazem","Felodipine"],"a":2,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000433, '2025', 65, NULL, 'Solution 2025.pdf', '{"no":65,"q":"A diabetic patient on insulin glargine and metformin has persistent hyperglycemia with HbA1c 8.3% and signs of heart failure. Which is the most appropriate medication to add next?","o":["Sitagliptin","Pioglitazone","Empagliflozin","Gliclazide"],"a":2,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000434, '2025', 66, NULL, 'Solution 2025.pdf', '{"no":66,"q":"A patient with atrial fibrillation and mitral stenosis presents within 4 hours of symptom onset and is hemodynamically stable. What is the next best step?","o":["Ventricular rate control","Cardioversion","Anticoagulation","Wait and watch"],"a":1,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000435, '2025', 67, NULL, 'Solution 2025.pdf', '{"no":67,"q":"A 2-year-old child presents to the emergency department with a generalized tonic-clonic seizure lasting 3 minutes associated with high fever 39.5◦C. The child has no previous seizure history or neurological problems. The seizure has now stopped, but parents are concerned about recurrence. What is the most appropriate immediate management for this febrile seizure?","o":["Ethosuximide","Sodium valproate","Diazepam","No antiepileptic medication needed"],"a":2,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000436, '2025', 68, NULL, 'Solution 2025.pdf', '{"no":68,"q":"A 45-year-old female presents with 6-month history of paroxysmal nocturnal dyspnea, palpitations and breathlessness. JVP is elevated, pulse is irregularly irregular, tender hep- NEET PG 2025 Page 56 of 175 © Collegedunia.com atomegaly is present, apex is heaving, and a mid-diastolic murmur is heard at the apex. She has a history of acute rheumatic fever. Which statement is false?","o":["This patient has an increased risk of stroke","The ‘a’ wave is absent in the JVP","This patient shows features of right heart failure","Presystolic accentuation is a hallmark feature"],"a":3,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000437, '2025', 69, NULL, 'Solution 2025.pdf', '{"no":69,"q":"A 15-year-old adolescent with known type 1 diabetes mellitus presents with fatigue, vom- iting and diarrhea. Random blood glucose is 700 mg/dL, serum sodium is 125 mEq/L, and potassium is 4.2 mEq/L. Which of the following is not recommended during initial manage- NEET PG 2025 Page 57 of 175 © Collegedunia.com ment?","o":["Administration of 3% saline","Initiation of 0.9% normal saline infusion","Intravenous insulin therapy","Frequent monitoring of serum potassium levels"],"a":0,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000438, '2025', 70, NULL, 'Solution 2025.pdf', '{"no":70,"q":"A patient presents with irregularly irregular pulse and palpitations. He arrives 2.5 hours after symptom onset. There is no history of diabetes and BP is 160/100 mmHg. What is the next best step?","o":["Control ventricular rate with verapamil","Emergent cardioversion","Transesophageal echo (TEE)","Wait and watch"],"a":0,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000439, '2025', 71, NULL, 'Solution 2025.pdf', '{"no":71,"q":"A 36-year-old woman with symmetrical small joint arthritis tests positive for anti-CCP. Which histological feature is most characteristic?","o":["Synovial granulomas","Pannus formation and reactive lymphocytic infiltrate","Uric acid crystal deposits","Non-caseating granulomas"],"a":1,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000440, '2025', 72, NULL, 'Solution 2025.pdf', '{"no":72,"q":"A 65-year-old man presents with enlarged hat size, shin pain, elevated alkaline phosphatase, and normal calcium and PTH levels. X-ray reveals mixed lytic and sclerotic bone lesions. What is the most likely diagnosis?","o":["Paget’s disease","Primary hyperparathyroidism","Osteomalacia","Bone metastasis"],"a":0,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000441, '2025', 73, NULL, 'Solution 2025.pdf', '{"no":73,"q":"A 64-year-old man with chronic kidney disease presents with pallor, exertional breathless- ness, and signs of heart failure. Investigations reveal normocytic anemia. What is the most appropriate next step in management?","o":["Oral iron","Darbepoetin alfa","Intravenous iron","Blood transfusion"],"a":0,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000442, '2025', 74, NULL, 'Solution 2025.pdf', '{"no":74,"q":"A 42-year-old woman presents with enlarged hands, coarsened facial features, and in- creased shoe size. Her IGF-1 level is elevated. Which of the following is the most specific test to confirm the diagnosis?","o":["Measurement of IGF-1 alone","Lack of GH suppression following oral glucose tolerance test (OGTT)","Lack of IGF-1 suppression after OGTT","Random growth hormone level"],"a":1,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000443, '2025', 75, NULL, 'Solution 2025.pdf', '{"no":75,"q":"A 54-year-old man with a history of chronic hyponatremia develops sudden-onset quadri- paresis after rapid sodium correction. Which investigation is most appropriate to confirm the diagnosis?","o":["Brainstem evoked potential","Electroencephalogram (EEG)","MRI of the brain","Nerve conduction studies"],"a":2,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000444, '2025', 76, NULL, 'Solution 2025.pdf', '{"no":76,"q":"Which hormone is elevated in Addison’s disease, leading to hyperpigmentation?","o":["Cortisol","ACTH","Aldosterone","Renin"],"a":1,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000445, '2025', 77, NULL, 'Solution 2025.pdf', '{"no":77,"q":"A 50-year-old man presents with altered sensorium and deep labored breathing. ABG shows: pH 7.20, pCO2 = 35 mmHg, HCO− 3 = 16 mEq/L, Na+ = 130 mEq/L, Cl−= 84 mEq/L, PaO2 = 80 mmHg. What is the most likely acid-base abnormality?","o":["Acute metabolic acidosis with AG 30","Chronic metabolic acidosis with AG 30","Acute respiratory acidosis","Chronic respiratory acidosis"],"a":0,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000446, '2025', 78, NULL, 'Solution 2025.pdf', '{"no":78,"q":"A patient collapses with breathlessness and pink frothy sputum. Autopsy shows hemosiderin- laden macrophages. In which condition is this not seen?","o":["Protein-losing enteropathy","Right heart failure","Volume overload","Pulmonary vein obstruction"],"a":0,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000447, '2025', 79, NULL, 'Solution 2025.pdf', '{"no":79,"q":"A 14-year-old boy presents with fatigue, mild jaundice, and splenomegaly. His hemoglobin is 10.5 g/dL, MCV is 82 fL, and MCHC is high at 37 g/dL. His father had a similar history of chronic anemia and underwent splenectomy. What is the most likely diagnosis?","o":["Autoimmune hemolytic anemia","Hereditary spherocytosis","Thalassemia minor","G6PD deficiency"],"a":1,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000448, '2025', 80, NULL, 'Solution 2025.pdf', '{"no":80,"q":"A patient arrives with hypotension, fever, joint pain, petechiae on limbs, and respiratory distress. Which of the following is the most likely diagnosis?","o":["Disseminated gonococcal infection","Septic shock","Rheumatoid arthritis","Septic arthritis"],"a":1,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000449, '2025', 81, NULL, 'Solution 2025.pdf', '{"no":81,"q":"A critically ill patient with COVID-19 is admitted to the ICU and is currently on mechanical ventilation. The PaO2/FiO2 ratio is 100, indicating severe ARDS. Which of the following is the most appropriate ventilatory strategy?","o":["High PEEP and low tidal volume","High PEEP and high tidal volume","Low PEEP and low tidal volume","Low PEEP and high tidal volume"],"a":0,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000450, '2025', 82, NULL, 'Solution 2025.pdf', '{"no":82,"q":"A 58-year-old patient has prolonged PT and factor IX deficiency. Parenteral vitamin K is planned. In which condition will this help?","o":["Hepatitis A","Pernicious anemia","Hemophilia B","Bile duct obstruction"],"a":3,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000451, '2025', 83, NULL, 'Solution 2025.pdf', '{"no":83,"q":"A case of sudden onset aphasia and right arm weakness for the last 5 hours is seen. Which investigation is indicated?","o":["MRI brain","Carotid Doppler","TEE","Transthoracic echocardiography"],"a":2,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000452, '2025', 84, NULL, 'Solution 2025.pdf', '{"no":84,"q":"A patient already on salbutamol and ipratropium continues to have nocturnal exacerbations of asthma. What is the next step? NEET PG 2025 Page 71 of 175 © Collegedunia.com","o":["Oral corticosteroids","Montelukast","LABA plus inhalation steroids","Increase the dose of salbutamol"],"a":2,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000453, '2025', 85, NULL, 'Solution 2025.pdf', '{"no":85,"q":"A 32-year-old male with history of recurrent paroxysmal supraventricular tachycardia is stable in sinus rhythm. What is the best choice for long-term prophylaxis?","o":["IV adenosine","IV esmolol","Oral diltiazem","IV amiodarone"],"a":2,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000454, '2025', 86, NULL, 'Solution 2025.pdf', '{"no":86,"q":"A farmer presents with a necrotic ulcerative skin lesion. Microscopy using polychrome methylene blue stain reveals capsulated bacilli showing a positive McFadyean reaction. What is the most likely causative organism?","o":["Clostridium perfringens","Bacillus anthracis","Yersinia pestis","Francisella tularensis"],"a":1,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000455, '2025', 87, NULL, 'Solution 2025.pdf', '{"no":87,"q":"Which structural component of Group A Streptococcus enables its attachment to pharyngeal epithelium by binding to fibronectin?","o":["Lipoprotein","Lipoteichoic acid","Capsule","Flagella"],"a":1,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000456, '2025', 88, NULL, 'Solution 2025.pdf', '{"no":88,"q":"Several residents in a village develop watery followed by bloody diarrhea after consuming unpasteurized milk. Stool microscopy reveals Gram-negative curved bacilli with polymor- phonuclear leukocytes. Identify the most likely pathogen.","o":["Clostridium perfringens","Staphylococcus aureus","Vibrio parahaemolyticus","Campylobacter jejuni"],"a":3,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000457, '2025', 89, NULL, 'Solution 2025.pdf', '{"no":89,"q":"A man presents with hemoptysis, fever, and breathlessness. Microscopic analysis of bronchoalveolar lavage reveals septate hyphae with acute angle branching. Which fungal NEET PG 2025 Page 75 of 175 © Collegedunia.com infection is most likely?","o":["Mucormycosis","Histoplasmosis","Aspergillosis","Candidiasis"],"a":2,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000458, '2025', 90, NULL, 'Solution 2025.pdf', '{"no":90,"q":"A 5-year-old child presents with intense perianal itching, predominantly during nighttime. Microscopic examination reveals an egg. Which organism is most likely responsible for the condition? NEET PG 2025 Page 76 of 175 © Collegedunia.com","o":["Enterobius vermicularis","Ancylostoma duodenale","Hymenolepis nana","Trichuris trichiura"],"a":0,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000459, '2025', 91, NULL, 'Solution 2025.pdf', '{"no":91,"q":"A patient presents with chronic cough, weight loss, and intermittent low-grade fever. Fungal culture from respiratory samples shows a yeast with narrow-based budding. Which of the following is the most probable diagnosis? NEET PG 2025 Page 77 of 175 © Collegedunia.com","o":["Blastomycosis","Histoplasmosis","Cryptococcosis","Coccidioidomycosis"],"a":1,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000460, '2025', 92, NULL, 'Solution 2025.pdf', '{"no":92,"q":"A case of brain abscess reveals Gram-positive, branching, filamentous organisms on NEET PG 2025 Page 78 of 175 © Collegedunia.com microscopy. The organism is weakly acid-fast and grows on paraffin bait media. Which is the most likely etiologic agent?","o":["Actinomyces israelii","Mycobacterium tuberculosis","Nocardia asteroides","Cryptococcus neoformans"],"a":2,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000461, '2025', 93, NULL, 'Solution 2025.pdf', '{"no":93,"q":"A case of recurrent Neisseria gonorrhoeae infection is being evaluated. Which immunologi- cal investigation would best detect a complement pathway defect? NEET PG 2025 Page 79 of 175 © Collegedunia.com","o":["C1 esterase inhibitor assay","Quantitative immunoglobulin levels","Nitroblue tetrazolium test","Terminal complement (C5–C9) assay"],"a":3,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
