INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000514, '2025', 146, NULL, 'Solution 2025.pdf', '{"no":146,"q":"A patient has a neck mass with odynophagia and dyspnea. Histology shows amyloid deposition. What is the most likely diagnosis?","o":["Papillary thyroid carcinoma","Follicular thyroid carcinoma","Medullary thyroid carcinoma","Anaplastic thyroid carcinoma"],"a":2,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000515, '2025', 147, NULL, 'Solution 2025.pdf', '{"no":147,"q":"A patient is diagnosed with AML M3. Which chromosomal translocation is characteristi- cally associated with this condition?","o":["t(9;22)","t(8;21)","t(15;17)","t(11;14)"],"a":2,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000516, '2025', 148, NULL, 'Solution 2025.pdf', '{"no":148,"q":"A 3-year-old child is brought to the emergency department with generalized convul- sions following a high-grade fever. Which of the following is the most appropriate first-line medication to manage seizures in this acute febrile episode?","o":["Diazepam","Valproate","Fosphenytoin","Doxycycline / Amoxicillin"],"a":0,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000517, '2025', 149, NULL, 'Solution 2025.pdf', '{"no":149,"q":"A 6-month-old infant presents with frequent infections and failure to thrive. Tests show adenosine deaminase (ADA) deficiency. Which immunodeficiency disorder is most likely responsible?","o":["Severe Combined Immunodeficiency (SCID)","Hypogammaglobulinemia","DiGeorge syndrome","Wiskott-Aldrich syndrome"],"a":0,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000518, '2025', 150, NULL, 'Solution 2025.pdf', '{"no":150,"q":"A family pedigree reveals multiple individuals with progressive eye movement limitation, retinal pigment changes, and disturbances in cardiac conduction. Based on these findings and the inheritance pattern, which of the following is the most probable diagnosis? vspace2mm","o":["Duchenne muscular dystrophy","Kearns–Sayre syndrome","Friedreich ataxia","Myotonic dystrophy"],"a":1,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000519, '2025', 151, NULL, 'Solution 2025.pdf', '{"no":151,"q":"A 2-year-old child has choked on a peanut. What is the most appropriate immediate management?","o":["Chest compressions","Back blows","Abdominal thrusts","Endotracheal intubation"],"a":2,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000520, '2025', 152, NULL, 'Solution 2025.pdf', '{"no":152,"q":"A child demonstrates progressive neurological decline and a cherry-red spot on fundus examination. Enzyme analysis reveals a deficiency in hexosaminidase A. What is the most likely diagnosis?","o":["GM1 gangliosidosis","GM2 gangliosidosis","Niemann–Pick disease","Gaucher disease"],"a":1,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000521, '2025', 153, NULL, 'Solution 2025.pdf', '{"no":153,"q":"A child with coarse facial features and developmental delay is found to have a deficiency of α-L-iduronidase on enzyme testing. Which substances are expected to accumulate in this disorder?","o":["Dermatan sulfate + Chondroitin sulfate","Only Dermatan sulfate","Dermatan sulfate + Heparan sulfate","Heparan sulfate + Chondroitin sulfate"],"a":2,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000522, '2025', 154, NULL, 'Solution 2025.pdf', '{"no":154,"q":"A 7-month-old infant has just started complementary feeding using the katori method. NEET PG 2025 Page 132 of 175 © Collegedunia.com What is the recommended quantity and frequency of feeding during the first day?","o":["1","1","1","1"],"a":0,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000523, '2025', 155, NULL, 'Solution 2025.pdf', '{"no":155,"q":"A neonate is born to an HIV-positive mother with a viral load of 1200 copies/mL. What is the recommended antiretroviral prophylaxis for the newborn?","o":["Nevirapine for 6 weeks with exclusive breastfeeding","Nevirapine + Zidovudine for 6 weeks with exclusive breastfeeding","No prophylaxis needed as mother is on ART","Nevirapine + Zidovudine for 12 weeks with exclusive breastfeeding"],"a":3,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000524, '2025', 156, NULL, 'Solution 2025.pdf', '{"no":156,"q":"A 5-year-old child with known chronic kidney disease presents with bowing of the legs. Lab results reveal normal calcium, elevated phosphate, increased alkaline phosphatase, and low 25(OH) Vitamin D. What is the most appropriate next intervention?","o":["Calcium supplementation with phosphate binder","Phosphate binder","Oral calcium with Vitamin D","Growth hormone therapy"],"a":0,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000525, '2025', 157, NULL, 'Solution 2025.pdf', '{"no":157,"q":"A 1-day-old newborn with significant respiratory distress is admitted to the ICU. Chest radiograph is performed. What is the most probable diagnosis based on the clinical and radiological findings? NEET PG 2025 Page 135 of 175 © Collegedunia.com","o":["Congenital Pulmonary Airway Malformation (CPAM)","Congenital Diaphragmatic Hernia (CDH)","Congenital lobar emphysema","Neonatal pneumonia"],"a":1,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
