INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000529, '2025', 161, NULL, 'Solution 2025.pdf', '{"no":161,"q":"A 60-year-old man with ischemic cardiomyopathy and palpitations is started on amio- darone. Which phase of the cardiac action potential is its primary site of action?","o":["Phase 0 – Rapid depolarization","Phase 2 – Plateau","Phase 3 – Repolarization","Phase 4 – Resting potential"],"a":2,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000530, '2025', 162, NULL, 'Solution 2025.pdf', '{"no":162,"q":"A patient presents with headache, palpitations, and diaphoresis with elevated 24-hour urine metanephrine levels. Which drug is given preoperatively?","o":["Phenoxybenzamine","Esmolol","CCB","Labetalol"],"a":3,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000531, '2025', 163, NULL, 'Solution 2025.pdf', '{"no":163,"q":"A 35-year-old woman is diagnosed with migraine and has a family history of coronary artery disease. She has been previously treated with sumatriptan. What is the drug of choice for migraine prophylaxis?","o":["Propranolol","Topiramate","Ergotamine","Naratriptan"],"a":0,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
