INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000533, '2025', 165, NULL, 'Solution 2025.pdf', '{"no":165,"q":"A 40-year-old male patient presents with GERD. Which of the following drugs helps in contraction of the lower esophageal sphincter and increases gastric emptying?","o":["Metoclopramide","Pantoprazole","Vonoprazan","Sodium alginate"],"a":0,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
