INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000535, '2025', 167, NULL, 'Solution 2025.pdf', '{"no":167,"q":"A patient with history of hypertension presents with renal stones. He was started on hydrochlorothiazide. Which statement is true regarding the choice of drug?","o":["Increased calcium excretion","Decreased calcium excretion","Increased oxalate absorption","Decreased citrate excretion"],"a":3,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000536, '2025', 168, NULL, 'Solution 2025.pdf', '{"no":168,"q":"A patient with HIV is recently diagnosed with multidrug-resistant tuberculosis. What is the appropriate regimen, and what should the patient be monitored for?","o":["BPaLM; monitor for immune reconstitution syndrome","INH + Levofloxacin + Pyrazinamide + Ethambutol; monitor for hepatotoxicity","INH + Levofloxacin + Streptomycin + Ethionamide; monitor for pyridoxine deficiency","INH + Clarithromycin + Pyrazinamide + Ethambutol; monitor for optic neuritis"],"a":0,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
