INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000538, '2025', 170, NULL, 'Solution 2025.pdf', '{"no":170,"q":"A patient has the following Starling forces measured at the capillary level: capillary hydrostatic pressure = 18 mmHg, capillary oncotic pressure = 27 mmHg, interstitial oncotic pressure = 7 mmHg. If there is no net movement of fluid across the capillary wall, what is the value of the interstitial hydrostatic pressure?","o":["0 mmHg","+1 mmHg","+2 mmHg","−2 mmHg"],"a":3,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000539, '2025', 171, NULL, 'Solution 2025.pdf', '{"no":171,"q":"A patient flying to high altitude of 3700 m develops headache, nausea, dyspnea, and dizziness. What explains these symptoms?","o":["Hypoxia causing vasodilation","Hypoxia causing vasoconstriction","Metabolic acidosis causing edema","High PO2 causing vasoconstriction"],"a":0,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000540, '2025', 172, NULL, 'Solution 2025.pdf', '{"no":172,"q":"In an experimental study, blood glucose levels were elevated to 2–3 times the normal and maintained at that level. What is the most likely pattern of insulin secretion in response?","o":["Rapid rise followed by a fall","Gradual rise followed by a fall","Remains persistently elevated","Initial rise followed by sustained elevation"],"a":3,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000541, '2025', 173, NULL, 'Solution 2025.pdf', '{"no":173,"q":"In the sarcomere length–tension relationship curve, at which point is the maximum active tension generated due to optimal overlap between actin and myosin filaments? NEET PG 2025 Page 149 of 175 © Collegedunia.com","o":["Point A","Point B","Point C","Point D"],"a":1,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000542, '2025', 174, NULL, 'Solution 2025.pdf', '{"no":174,"q":"A patient presents with fatigue, muscle cramps, and strong salt cravings. What is the most likely diagnosis? NEET PG 2025 Page 150 of 175 © Collegedunia.com","o":["Addison’s disease","Conn’s disease","Cushing’s disease","Hypopituitarism"],"a":0,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
