INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000544, '2025', 176, NULL, 'Solution 2025.pdf', '{"no":176,"q":"A woman presenting with amenorrhea and galactorrhea is diagnosed with a pituitary adenoma and elevated prolactin levels. What is the most likely cause of her amenorrhea?","o":["Low GnRH","High pulsed LH","High FSH","Inhibition of GnRH by prolactin"],"a":0,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000545, '2025', 177, NULL, 'Solution 2025.pdf', '{"no":177,"q":"A schizophrenia patient on haloperidol was responding well for the last 2 years. Now he presents with orofacial dyskinesia, choreiform, tic-like movements, and dystonia features. What can be the probable diagnosis and treatment?","o":["Acute dystonia – Ropinirole","Tardive dyskinesia – Valbenazine","Akathisia – Propranolol","Oral tremor – Amantadine"],"a":1,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
