INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000547, '2025', 179, NULL, 'Solution 2025.pdf', '{"no":179,"q":"Mr. K was brought to a psychiatrist by his friend, saying that Mr. K needs everything to be in perfect order and has difficulty in getting rid of things stored with him, both of which are affecting his work quality. He is a perfectionist. However, Mr. K denies such complaints. What is the diagnosis?","o":["Narcissistic personality","Obsessive Compulsive Personality Disorder","Paranoid delusion","Dependent personality"],"a":1,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
