INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000549, '2025', 181, NULL, 'Solution 2025.pdf', '{"no":181,"q":"A 21-year-old female presents with amnesia of events following her father’s death in a road traffic accident. Symptoms have persisted for 2 weeks, and she experiences flashbacks. What is the most probable diagnosis?","o":["Dissociative disorder","Major depression","PTSD","Acute stress disorder"],"a":3,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
INSERT OR IGNORE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (20000550, '2025', 182, NULL, 'Solution 2025.pdf', '{"no":182,"q":"A person attacks his co-worker, complaining that the co-worker has been plotting to harm him. He hears voices. On examination, the person is found to have disorganized speech. What is the next step in this case?","o":["Refer for anger management","Refer for psychiatric assessment and check if he is fit for trial","He is not responsible because he is mentally ill","Start immediate trials and punishment"],"a":1,"year":"2025","paper":"2025","source_file":"Solution 2025.pdf","image_based":false}');
